'use strict';
const V=ChartViewCore;
state.qualityView={focus:'individuals',range:{start:'',end:''}};
const viewText=(key,args=[])=>I18n.t('chartview.'+key,args);
function resetQualityRange(){state.qualityView.range={start:'',end:''};}
function qualityView(r){return V.windowFor(r,state.quality.order==='date'?'date':'index',state.qualityView.range);}
function qualityClock(){const q=state.quality;return q.date>=0&&ImportCore.date(state.result?.input[0]?.row[q.date],!!state.data.date1904)?.kind==='instant'?'utc':'wall';}
function qualityViewDescription(view){return viewText(view.mode==='date'?'period':'positions',[view.start,view.end]);}
function qualityStamp(ms,withTime=true){return Number.isFinite(ms)?new Date(ms).toISOString().slice(0,withTime?19:10).replace('T',' '):'';}
function qualityViewControls(r){const d=state.data,q=state.quality,view=r?qualityView(r):null,dateMode=view?.mode==='date',valid=!!view?.valid,disabled=!r?'disabled':'',from=valid?Math.max(view.min,Math.min(view.max,view.from)):view?.min||0,to=valid?Math.max(view.min,Math.min(view.max,view.to)):view?.max||0;
  return `<section class="panel quality-view-controls" id="quality-view-controls"><div class="quality-near-controls"><div><label for="column">${viewText('characteristic')}</label><select id="column">${options(d.headers,state.col)}</select></div><div><label for="qc-date">${viewText('dateColumn')}</label><select id="qc-date"><option value="-1">${I18n.t('quality-ui.3b69e57819')}</option>${options(d.headers,q.date)}</select></div><div><label for="qc-order">${viewText('order')}</label><select id="qc-order"><option value="input" ${q.order==='input'?'selected':''}>${I18n.t('quality-ui.c983874dc2')}</option><option value="date" ${q.order==='date'?'selected':''}>${I18n.t('quality-ui.df1683cddc')}</option></select></div></div><div class="quality-date-controls"><div><label for="qc-start-date">${viewText('start')}</label><input type="date" id="qc-start-date" value="${esc(dateMode?(state.qualityView.range.start||view.start):'')}" ${dateMode?'':'disabled'}></div><div><label for="qc-end-date">${viewText('end')}</label><input type="date" id="qc-end-date" value="${esc(dateMode?(state.qualityView.range.end||view.end):'')}" ${dateMode?'':'disabled'}></div><button id="qc-range-reset" ${disabled}>${viewText('reset')}</button></div><div class="quality-range-status" id="qc-range-status" role="status">${view&&valid?esc(qualityViewDescription(view)):''}</div><div class="quality-range-slider ${!r?'is-disabled':''}" id="qc-range-slider"><div class="range-rail"><div class="range-fill" id="qc-range-fill"></div></div><input type="range" id="qc-range-start" aria-label="${esc(viewText('from'))}" min="${view?.min||0}" max="${view?.max||0}" step="1" value="${from}" ${disabled}><input type="range" id="qc-range-end" aria-label="${esc(viewText('to'))}" min="${view?.min||0}" max="${view?.max||0}" step="1" value="${to}" ${disabled}></div><div class="range-endpoints"><span>${view?(dateMode?V.isoDay(view.min):view.min):''}</span><span>${view?(dateMode?V.isoDay(view.max):view.max):''}</span></div><p class="section-note">${view&&dateMode?viewText(qualityClock()):viewText('indexHelp')}</p>${r?`<p class="view-scope-note">${viewText('global',[r.n])}</p>`:''}<div class="chart-focus-options" role="group" aria-label="${esc(viewText('focus'))}">${[['individuals',r?.chart==='xbar'?'Xbar':'Individuals'],['mr',r?.chart==='xbar'?'R':'MR'],['histogram',I18n.t('quality-ui.57cdca78cc')]].map(([id,label])=>`<button data-chart-focus="${id}" aria-pressed="${state.qualityView.focus===id}">${label}</button>`).join('')}</div></section>`;
}
function qualityPanels(r){const view=qualityView(r),first=r.chart==='imr'?I18n.t('quality-ui.8642a9d0dc'):I18n.t('quality-ui.c2b856ce7c'),second=r.chart==='imr'?I18n.t('quality-ui.41550f339d'):I18n.t('quality-ui.bd2c380870'),focus=state.qualityView.focus;
  const panel=(id,label,body,notes,count='')=>`<section class="panel quality-chart-panel ${id===focus?'expanded-chart':''}" data-quality-chart="${id}"><div class="chart-title"><h3>${label}</h3><button data-expand-chart="${id}" aria-pressed="${id===focus}">${viewText(id===focus?'expanded':'expand')}</button></div>${count?`<p class="chart-point-count">${count}</p>`:''}<div class="chart-viewport">${body}</div><p class="section-note">${notes}</p></section>`;
  function control(id,label,records,total,center,lcl,ucl,alarms,note){const count=viewText('count',[Math.min(records.length,500),total,records.length>500?viewText('capped'):'']);const tip=id==='individuals'?formulaTip(I18n.t('quality-ui.85140e9ead'),r.chart==='imr'?I18n.t('quality-ui.3fd47dadf2'):I18n.t('quality-ui.85e1d9498e')):formulaTip(I18n.t('quality-ui.8b29c000ed'),I18n.t('quality-ui.cdfe0da8ed'));return panel(id,label+' '+tip,!view.valid?`<p class="notice error" role="alert">${viewText('invalid')}</p>`:!records.length?`<p class="empty">${viewText('empty')}</p>`:spcChart(records,center,lcl,ucl,label,{axis:view.axis,width:id===focus?1100:620,height:id===focus?300:260,lsl:id==='individuals'&&r.chart==='imr'?r.lsl:null,usl:id==='individuals'&&r.chart==='imr'?r.usl:null,alarms,utc:qualityClock()==='utc'}),`CL ${fmt(center)} · LCL ${fmt(lcl)} · UCL ${fmt(ucl)}<br>${esc(note)}`,count);}
  const panels={individuals:control('individuals',first,view.first,view.firstTotal,r.mean,r.lcl,r.ucl,r.alarms,(r.chart==='xbar'?viewText('groupNote')+' ':'')+viewText('rulesNote')),mr:control('mr',second,view.ranges,view.rangeTotal,r.rangeMean,r.rangeLcl,r.rangeUcl,r.rangeSignals,viewText(r.chart==='imr'?'mrNote':'groupNote')),histogram:panel('histogram',I18n.t('quality-ui.57cdca78cc'),histogram(r,{width:focus==='histogram'?1100:620,height:focus==='histogram'?300:260}),esc(viewText('histogramNote')))};
  return `<div class="quality-chart-grid">${[focus,...['individuals','mr','histogram'].filter(id=>id!==focus)].map(id=>panels[id]).join('')}</div>`;
}
function updateQualityPlots(){const r=state.result;if(!r)return;const view=qualityView(r);$('#quality-plots').innerHTML=qualityPanels(r);$('#qc-range-status').textContent=view.valid?qualityViewDescription(view):viewText('invalid');const width=Math.max(1,view.max-view.min),lo=Math.max(0,Math.min(100,100*(view.from-view.min)/width)),hi=Math.max(0,Math.min(100,100*(view.to-view.min)/width));$('#qc-range-fill').style.left=(view.valid?lo:0)+'%';$('#qc-range-fill').style.width=(view.valid?hi-lo:0)+'%';
  if(view.valid){$('#qc-range-start').value=Math.max(view.min,Math.min(view.max,view.from));$('#qc-range-end').value=Math.max(view.min,Math.min(view.max,view.to));$('#qc-range-start').setAttribute('aria-valuetext',view.start);$('#qc-range-end').setAttribute('aria-valuetext',view.end);if(view.mode==='date'){$('#qc-start-date').value=state.qualityView.range.start||view.start;$('#qc-end-date').value=state.qualityView.range.end||view.end;}}
  $$('[data-chart-focus]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.chartFocus===state.qualityView.focus)));$$('[data-expand-chart]').forEach(b=>b.onclick=()=>{state.qualityView.focus=b.dataset.expandChart;updateQualityPlots();document.querySelector('[data-chart-focus="'+state.qualityView.focus+'"]').focus({preventScroll:true});$('#quality-view-controls').scrollIntoView({block:'start',behavior:'smooth'});});
}
function bindQualityView(){for(const id of ['qc-start-date','qc-end-date'])$('#'+id).onchange=()=>{state.qualityView.range={start:$('#qc-start-date').value,end:$('#qc-end-date').value};updateQualityPlots();};
  for(const [id,key,other] of [['qc-range-start','start','qc-range-end'],['qc-range-end','end','qc-range-start']])$('#'+id).oninput=e=>{const view=qualityView(state.result),n=Number(e.target.value),bound=Number($('#'+other).value),value=key==='start'?Math.min(n,bound):Math.max(n,bound);state.qualityView.range[key]=view.mode==='date'?V.isoDay(value):String(value);updateQualityPlots();};
  $('#qc-range-reset').onclick=()=>{resetQualityRange();updateQualityPlots();};$$('[data-chart-focus]').forEach(b=>b.onclick=()=>{state.qualityView.focus=b.dataset.chartFocus;updateQualityPlots();});updateQualityPlots();
}

function qualityReportChart(r,view,range=false){const records=range?view.ranges:view.first,total=range?view.rangeTotal:view.firstTotal,plot=records.length?spcChart(records,range?r.rangeMean:r.mean,range?r.rangeLcl:r.lcl,range?r.rangeUcl:r.ucl,range?'MR / R':'I / Xbar',{alarms:range?r.rangeSignals:r.alarms,axis:view.axis,utc:qualityClock()==='utc'}):reportText(viewText('empty'));return plot+reportText(viewText('count',[Math.min(records.length,500),total,records.length>500?viewText('capped'):''])+' '+viewText('reportMax')+' '+viewText(range?(r.chart==='imr'?'mrNote':'groupNote'):'rulesNote'));}
